// Pilot rows -> Cloud rows for one tenant. tenant_id is added, covers are dropped (the owner re-uploads them), receipts
// are not copied but their keys move under the tenant prefix, student ids are regenerated by inserting in old-id order,
// and every other value (including reviewed_by) is copied verbatim. Run the preflight first. No dependencies.
import { IMPORT_COLUMNS, IMPORT_TABLES } from "./columns.mjs";

const RECEIPT_KEY = /^receipts\/(.+)\.(jpg|png|webp|pdf)$/;

/** Returns { collections, payments, students, bank_movements }: arrays of Cloud rows in insert order. */
export function transform(db, { tenantId }) {
  const out = {};
  for (const table of IMPORT_TABLES) {
    const source = IMPORT_COLUMNS[table].filter((c) => c !== "tenant_id");
    out[table] = db.prepare(`SELECT ${source.join(", ")}${table === "students" ? ", id AS old_id" : ""} FROM ${table} ORDER BY ${table === "students" ? "old_id" : "id"}`).all().map((row) => {
      const { old_id, ...rest } = row;
      const cloud = { tenant_id: tenantId, ...rest };
      if (table === "collections") cloud.cover_key = null;
      if (table === "payments") cloud.receipt_key = `t/${tenantId}/receipts/${cloud.id}.${RECEIPT_KEY.exec(cloud.receipt_key)[2]}`;
      return cloud;
    });
  }
  return out;
}
